// Quantized poses use 44 bytes. All clients send their own pose directly to the relay.
export const POSE_BYTES=44;
export const roundHash=s=>{let h=2166136261;for(const c of String(s||''))h=Math.imul(h^c.charCodeAt(0),16777619);return h>>>0;};
const bounded=(n,a,b)=>Math.max(a,Math.min(b,Number(n)||0));
export function encodePose(actor,seq,at,p,round){const b=new ArrayBuffer(POSE_BYTES),d=new DataView(b);d.setUint8(0,1);d.setUint8(1,p.reset?1:0);d.setUint16(2,seq&65535,true);d.setUint32(4,parseInt(actor,16)>>>0,true);d.setUint32(8,Math.trunc(at)>>>0,true);d.setInt32(12,Math.round(bounded(p.x,-1e6,1e6)*100),true);d.setInt32(16,Math.round(bounded(p.z,-1e6,1e6)*100),true);d.setInt16(20,Math.round(Math.atan2(Math.sin(p.heading||0),Math.cos(p.heading||0))/Math.PI*32767),true);d.setUint16(22,Math.round(bounded(p.speed,0,112)*100),true);d.setInt16(24,Math.round(bounded(p.lean,-2.5,2.5)*10000),true);d.setInt16(26,Math.round(bounded(p.pitch,-2.5,2.5)*10000),true);d.setUint16(28,Math.round(bounded(p.wheelie,0,1)*10000),true);d.setUint16(30,Math.round(bounded(p.crash,0,6)*1000),true);d.setInt32(32,Math.round(bounded(p.progress,-1e6,1e6)*100),true);d.setFloat32(36,Number.isFinite(p.wheelTravel??p.travel)?p.wheelTravel??p.travel:0,true);d.setUint32(40,roundHash(round),true);return b;}
export function decodePose(buffer,now=Date.now()){const bytes=buffer instanceof Uint8Array?buffer:new Uint8Array(buffer);if(bytes.byteLength!==POSE_BYTES)return null;const d=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);if(d.getUint8(0)!==1)return null;const raw=d.getUint32(8,true),at=now+((raw-(Math.trunc(now)>>>0)+2147483648)>>>0)-2147483648,p={id:d.getUint32(4,true).toString(16).padStart(8,'0'),seq:d.getUint16(2,true),at,x:d.getInt32(12,true)/100,z:d.getInt32(16,true)/100,heading:d.getInt16(20,true)/32767*Math.PI,speed:d.getUint16(22,true)/100,lean:d.getInt16(24,true)/10000,pitch:d.getInt16(26,true)/10000,wheelie:d.getUint16(28,true)/10000,crash:d.getUint16(30,true)/1000,progress:d.getInt32(32,true)/100,travel:d.getFloat32(36,true),round:d.getUint32(40,true)};return Object.values(p).every(v=>typeof v!=='number'||Number.isFinite(v))?p:null;}
const utf8=new TextEncoder(),text=new TextDecoder();
export function encodeBroadcast(topic,event,payload,joinRef='1',ref=''){const fields=[joinRef,ref,topic,event,''].map(s=>utf8.encode(s));if(fields.some(a=>a.length>255))throw Error('Metadati Realtime troppo lunghi');const bytes=payload instanceof Uint8Array?payload:new Uint8Array(payload),out=new Uint8Array(7+fields.reduce((n,a)=>n+a.length,0)+bytes.length);out.set([3,...fields.map(a=>a.length),0]);let i=7;for(const a of fields){out.set(a,i);i+=a.length;}out.set(bytes,i);return out.buffer;}
export function decodeBroadcast(buffer){const b=buffer instanceof Uint8Array?buffer:new Uint8Array(buffer);if(b.length<5||b[0]!==4)return null;const lengths=[b[1],b[2],b[3]],encoding=b[4];let at=5;const fields=[];for(const n of lengths){if(at+n>b.length)return null;fields.push(text.decode(b.subarray(at,at+n)));at+=n;}let payload=b.subarray(at);if(encoding===1){try{payload=JSON.parse(text.decode(payload));}catch{return null;}}return{topic:fields[0],event:fields[1],metadata:fields[2],payload};}
export function poseChanged(a,b){return !a||Math.hypot(a.x-b.x,a.z-b.z)>.025||Math.abs(Math.atan2(Math.sin(a.heading-b.heading),Math.cos(a.heading-b.heading)))>.004||Math.abs(a.speed-b.speed)>.12||Math.abs((a.lean||0)-(b.lean||0))>.012||Math.abs((a.wheelie||0)-(b.wheelie||0))>.015||Math.abs((a.crash||0)-(b.crash||0))>.05;}
export function sendInterval(p,players=2){if((p.speed||0)<.2&&Math.abs(p.lean||0)<.01&&!(p.crash>0))return 1000;const n=Math.max(2,players);return Math.ceil(1000/Math.min(10,70/(n*n)));}
